    String summary(JSONObject t){if(t==null)return "";JSONArray ex=t.optJSONArray("exercises");if(ex==null)return "";int seconds=0;for(int i=0;i<ex.length();i++){JSONObject p=ex.optJSONObject(i);seconds+=p.has("estimated_seconds")&&!p.isNull("estimated_seconds")?p.optInt("estimated_seconds"):p.optInt("sets",1)*(45+p.optInt("rest_seconds",120))+60;}return ex.length()+(ex.length()==1?" exercise":" exercises")+" · about "+Math.round(seconds/60f)+" min";}
