    private String briefState(String status,String location){
        switch(status){
            case "writing":return "Your coach is writing. Read it in "+location+".";
            case "waiting":return "Brief queued. Read it in "+location+" when the coach is back online.";
            case "failed":return "Your coach couldn't write this.";
            case "unavailable":return "Coach offline. The brief appears in "+location+" once it can be prepared.";
            default:return "Check "+location+" for the brief.";
        }
    }
